// recover 必须在 defer 中使用
func safeDiv(a, b int) (result int, err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("panic: %v", r)
		}
	}()
	return a / b, nil // b==0 时 panic
}

result, err := safeDiv(10, 0)
// result=0, err="panic: runtime error: integer divide by zero"

// ❌ 错误用法：不在 defer 中
func wrong() {
	if r := recover(); r != nil { /* 永远不会执行 */ }
	panic("boom")
}

func TestAdd(t *testing.T) {
	cases := []struct {
		name     string
		a, b     int
		expected int
	}{
		{"positive", 1, 2, 3},
		{"negative", -1, -2, -3},
		{"zero", 0, 0, 0},
		{"mixed", -1, 1, 0},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := Add(tc.a, tc.b)
			if got != tc.expected {
				t.Errorf("Add(%d,%d) = %d, want %d",
					tc.a, tc.b, got, tc.expected)
			}
		})
	}
}

func BenchmarkAdd(b *testing.B) {
	for i := 0; i < b.N; i++ {
		Add(1, 2)
	}
}
